 const [termNumber,setTermNumber]=useState("3"),[weekNumber,setWeekNumber]=useState("1"),[lessonNumber,setLessonNumber]=useState("");
 const [weeks,setWeeks]=useState(2),[periods,setPeriods]=useState(5),[termStart,setTermStart]=useState(new Date().toISOString().slice(0,10));
 const [duration,setDuration]=useState(40),[marks,setMarks]=useState(20),[questions,setQuestions]=useState(10),[busy,setBusy]=useState(false),[error,setError]=useState("");

